import DashboardLayout from "@/components/DashboardLayout";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { trpc } from "@/lib/trpc";
import { ArrowRight, Banknote, Building2, FilePlus2, FileText, FolderOpen, Landmark, Pencil, Plus, Receipt, Search, ShieldCheck, Users, WalletCards } from "lucide-react";
import { useMemo, useState } from "react";
import { useLocation } from "wouter";

const money = new Intl.NumberFormat("en-US", { maximumFractionDigits: 2 });
const today = () => new Date().toISOString().slice(0, 10);

type InvoiceStatus = "draft" | "posted";

export default function SalesCollections() {
  const [, setLocation] = useLocation();
  const utils = trpc.useUtils();
  const { data: me } = trpc.auth.me.useQuery();
  const { data: memberships = [] } = trpc.erp.members.mine.useQuery();
  const canRecord = me?.role === "admin" || memberships.some((member) => ["manager", "finance", "input"].includes(member.projectRole));
  const { data: projects = [] } = trpc.erp.projects.list.useQuery();
  const { data: units = [] } = trpc.erp.units.list.useQuery();
  const { data: sales = [] } = trpc.erp.sales.list.useQuery();
  const { data: collections = [] } = trpc.erp.collections.list.useQuery();
  const { data: customersAndSuppliers = [] } = trpc.erp.vendors.list.useQuery();
  const { data: documents = [] } = trpc.erp.accounting.documents.list.useQuery();
  const { data: certificates = [] } = trpc.erp.certificates.list.useQuery();
  const { data: accounts = [] } = trpc.erp.accounting.accounts.list.useQuery();
  const { data: cashAccounts = [] } = trpc.erp.cashAccounts.list.useQuery();
  const createUnit = trpc.erp.units.create.useMutation({ onSuccess: () => { void utils.erp.units.list.invalidate(); setUnit(emptyUnit); setMessage("تم إنشاء الوحدة وإتاحتها للبيع."); } });
  const createSale = trpc.erp.sales.create.useMutation();
  const createInvoice = trpc.erp.accounting.documents.create.useMutation();
  const createCertificate = trpc.erp.certificates.create.useMutation({ onSuccess: () => { void utils.erp.certificates.list.invalidate(); setCertificate(emptyCertificate); setMessage("تم إنشاء مستخلص البيع على الخارطة وإرساله لمسار اعتماد أمين المشروع."); } });
  const updateCertificate = trpc.erp.certificates.update.useMutation({ onSuccess: () => { void utils.erp.certificates.list.invalidate(); setMessage("تم تعديل المستخلص وإعادة إرساله لمسار الاعتماد."); }, onError: (error) => setMessage(error.message || "تعذر تعديل المستخلص.") });
  const updateUnit = trpc.erp.units.update.useMutation({ onSuccess: () => { void utils.erp.units.list.invalidate(); setMessage("تم تعديل بيانات الوحدة."); }, onError: (error) => setMessage(error.message || "تعذر تعديل الوحدة.") });
  const updateSale = trpc.erp.sales.update.useMutation({ onSuccess: () => { void utils.erp.sales.list.invalidate(); void utils.erp.accounting.documents.list.invalidate(); setMessage("تم تعديل حركة البيع."); }, onError: (error) => setMessage(error.message || "تعذر تعديل البيع.") });
  const updateCollection = trpc.erp.collections.update.useMutation({ onSuccess: () => { void utils.erp.collections.list.invalidate(); setMessage("تم تعديل التحصيل."); }, onError: (error) => setMessage(error.message || "تعذر تعديل التحصيل.") });
  const updateInvoice = trpc.erp.accounting.documents.update.useMutation({ onSuccess: () => { void utils.erp.accounting.documents.list.invalidate(); setMessage("تم تعديل فاتورة المبيعات."); }, onError: (error) => setMessage(error.message || "تعذر تعديل الفاتورة.") });
  const deleteInvoice = trpc.erp.accounting.documents.delete.useMutation({ onSuccess: () => { void utils.erp.accounting.documents.list.invalidate(); setMessage("تم حذف الفاتورة وتسجيل العملية في التدقيق."); }, onError: (error) => setMessage(error.message || "تعذر حذف الفاتورة.") });
  const deleteCertificate = trpc.erp.certificates.delete.useMutation({ onSuccess: () => { void utils.erp.certificates.list.invalidate(); setMessage("تم حذف المستخلص وتسجيل العملية في التدقيق."); }, onError: (error) => setMessage(error.message || "تعذر حذف المستخلص.") });
  const deleteCollection = trpc.erp.collections.delete.useMutation({ onSuccess: () => { void utils.erp.collections.list.invalidate(); setMessage("تم حذف التحصيل وتسجيل العملية في التدقيق."); }, onError: (error) => setMessage(error.message || "تعذر حذف التحصيل.") });
  const updateCustomer = trpc.erp.sales.updateCustomer.useMutation({ onSuccess: () => { void utils.erp.sales.list.invalidate(); setEditingCustomer(null); setMessage("تم تحديث بيانات العميل."); } });
  const createCollection = trpc.erp.collections.create.useMutation({ onSuccess: () => { void utils.erp.collections.list.invalidate(); void utils.erp.dashboard.summary.invalidate(); void utils.erp.reports.financialSummary.invalidate(); void utils.erp.reports.cashFlow.invalidate(); setCollection(emptyCollection); setMessage("تم تسجيل التحصيل وإرساله لمسار الاعتماد."); } });
  const createCustomer = trpc.erp.vendors.create.useMutation({ onSuccess: () => { void utils.erp.vendors.list.invalidate(); setCustomerForm(emptyCustomer); setCustomerOpen(false); setMessage("تم إنشاء العميل وأصبح متاحًا في فاتورة المبيعات."); } });
  const [activeTab, setActiveTab] = useState<"overview" | "invoice" | "offPlanCertificate" | "documents" | "collections" | "customers" | "units">("overview");
  const [search, setSearch] = useState("");
  const [message, setMessage] = useState("");
  const [documentFilter, setDocumentFilter] = useState<"all" | "invoice" | "certificate" | "collection">("all");
  const [documentSearch, setDocumentSearch] = useState("");
  const [previewDocument, setPreviewDocument] = useState<any>(null);
  const [customerOpen, setCustomerOpen] = useState(false);
  const [editingCustomer, setEditingCustomer] = useState<{ id: number; name: string; phone: string } | null>(null);
  const [invoicePreview, setInvoicePreview] = useState<any>(null);
  const [unit, setUnit] = useState(emptyUnit);
  const [sale, setSale] = useState({ projectId: "", unitId: "", customerId: "", customerName: "", customerPhone: "", customerNationalAddress: "", customerTaxNumber: "", saleDate: today(), preTaxAmount: "", taxRate: "15", itemDescription: "", relatedDocumentType: "quotation" as "quotation" | "certificate", relatedDocumentId: "", status: "draft" as InvoiceStatus });
  const [collection, setCollection] = useState(emptyCollection);
  const [certificate, setCertificate] = useState(emptyCertificate);
  const [customerForm, setCustomerForm] = useState(emptyCustomer);

  const customers = customersAndSuppliers.filter((item) => item.partyType === "customer");
  const salesInvoices = documents.filter((item) => item.documentType === "sales_invoice" || item.documentType === "credit_note");
  const quotations = documents.filter((item) => item.documentType === "quotation");
  const offPlanCertificates = useMemo(() => certificates.filter((certificate) => projects.some((project) => project.id === certificate.projectId && project.projectType === "off_plan_sales")), [certificates, projects]);
  const filteredCustomers = customers.filter((customer) => `${customer.name} ${customer.phone || ""} ${customer.taxNumber || ""}`.toLowerCase().includes(search.toLowerCase()));
  const selectedProject = projects.find((project) => project.id === Number(sale.projectId));
  const selectedCustomer = customers.find((customer) => customer.id === Number(sale.customerId));
  const availableUnits = units.filter((item) => item.status === "available" && (!sale.projectId || item.projectId === Number(sale.projectId)));
  const relatedOptions = sale.relatedDocumentType === "quotation" ? quotations.map((item) => ({ value: String(item.id), label: `${item.documentNumber || `عرض سعر #${item.id}`} — ${item.partyName || "بدون عميل"}` })) : offPlanCertificates.map((item) => ({ value: String(item.id), label: `${item.certificateNumber || `مستخلص #${item.id}`} — مستخلص بيع على الخارطة` }));
  const baseAmount = Number(sale.preTaxAmount || 0);
  const taxAmount = baseAmount * Number(sale.taxRate || 0) / 100;
  const totalAmount = baseAmount + taxAmount;
  const revenueAccount = accounts.find((account) => account.code === "4101") || accounts.find((account) => account.accountType === "revenue" && account.isPostable);
  const activeProjects = projects.filter((project) => project.status !== "archived");
  const totalSales = sales.reduce((sum, item) => sum + Number(item.totalAmount || 0), 0);
  const totalCollected = collections.filter((item) => item.status === "received").reduce((sum, item) => sum + Number(item.amount || 0), 0);
  const totalOutstanding = Math.max(totalSales - totalCollected, 0);

  const submitSaleInvoice = (event: React.FormEvent) => {
    event.preventDefault();
    const projectId = Number(sale.projectId);
    const unitId = Number(sale.unitId);
    const customerName = selectedCustomer?.name || sale.customerName.trim();
    if (!projectId || !unitId || !customerName || !baseAmount || !sale.itemDescription.trim() || !revenueAccount) { setMessage("أكمل المشروع والوحدة والعميل ووصف البند والمبلغ، وتأكد من وجود حساب الإيراد 4101."); return; }
    const relatedDocumentId = sale.relatedDocumentId ? Number(sale.relatedDocumentId) : undefined;
    setMessage("جارٍ حفظ البيع وإنشاء الفاتورة وربطها بالإيراد...");
    createSale.mutate({ projectId, unitId, customerName, customerPhone: selectedCustomer?.phone || sale.customerPhone || undefined, saleDate: sale.saleDate || undefined, preTaxAmount: baseAmount, taxRate: Number(sale.taxRate) }, {
      onSuccess: (createdSale) => {
        createInvoice.mutate({ documentType: "sales_invoice", projectId, relatedDocumentType: relatedDocumentId ? sale.relatedDocumentType : undefined, relatedDocumentId, partyName: customerName, partyTaxNumber: selectedCustomer?.taxNumber || sale.customerTaxNumber || undefined, documentDate: sale.saleDate || undefined, amount: baseAmount, taxAmount, totalAmount, status: sale.status, notes: `${selectedProject?.projectType === "off_plan_sales" ? "فاتورة بيع وحدة على الخارطة — التحصيل يوجه إلى حساب الضمان حسب الوجهة المحددة." : "فاتورة مبيعات مرتبطة بالمشروع والوحدة."}${sale.customerNationalAddress ? ` العنوان الوطني للعميل: ${sale.customerNationalAddress}.` : ""}`, lines: [{ accountId: revenueAccount.id, projectId, description: sale.itemDescription.trim(), debit: 0, credit: totalAmount }] }, {
          onSuccess: () => { void utils.erp.sales.list.invalidate(); void utils.erp.accounting.documents.list.invalidate(); void utils.erp.units.list.invalidate(); void utils.erp.dashboard.summary.invalidate(); setMessage("تم حفظ البيع والفاتورة الضريبية وربطهما بالمشروع والعميل."); setInvoicePreview({ documentNumber: `فاتورة بيع #${createdSale.id}`, partyName: customerName, projectName: selectedProject?.name, amount: baseAmount, taxAmount, totalAmount, documentDate: sale.saleDate, description: sale.itemDescription, customerTaxNumber: sale.customerTaxNumber, customerNationalAddress: sale.customerNationalAddress }); setSale((current) => ({ ...current, unitId: "", itemDescription: "", preTaxAmount: "", relatedDocumentId: "" })); },
          onError: (error) => setMessage(`تم تسجيل البيع لكن تعذر إنشاء الفاتورة: ${error.message}`),
        });
      },
      onError: (error) => setMessage(error.message || "تعذر حفظ البيع."),
    });
  };

  const submitCertificate = (event: React.FormEvent) => {
    event.preventDefault();
    const projectId = Number(certificate.projectId);
    const project = projects.find((item) => item.id === projectId);
    if (!projectId || project?.projectType !== "off_plan_sales" || !certificate.certificateNumber.trim() || !certificate.preTaxAmount || !certificate.description.trim()) { setMessage("حدد مشروع بيع على الخارطة ورقم المستخلص والوصف والمبلغ قبل الحفظ."); return; }
    const unitText = certificate.unitReferences.trim() ? `الوحدات المشمولة: ${certificate.unitReferences.trim()}` : "";
    createCertificate.mutate({ projectId, certificateNumber: certificate.certificateNumber.trim(), description: `${certificate.description.trim()}${unitText ? ` — ${unitText}` : ""}`, technicalSpecifications: certificate.technicalSpecifications.trim() || undefined, preTaxAmount: Number(certificate.preTaxAmount), taxRate: Number(certificate.taxRate), certificateDate: certificate.certificateDate || undefined });
  };

  const editUnit = (item: any) => { const name = window.prompt("اسم الوحدة", item.name); const price = Number(window.prompt("السعر الإرشادي", String(item.listPrice)) || item.listPrice); if (!name?.trim()) return; updateUnit.mutate({ id: item.id, projectId: item.projectId, code: item.code, name: name.trim(), type: item.type || undefined, listPrice: price, status: item.status }); };
  const editSale = (item: any) => { const customerName = window.prompt("اسم العميل", item.customerName); const amount = Number(window.prompt("المبلغ قبل الضريبة", String(item.preTaxAmount)) || item.preTaxAmount); if (!customerName?.trim() || !amount) return; updateSale.mutate({ id: item.id, projectId: item.projectId, unitId: item.unitId, customerName: customerName.trim(), customerPhone: item.customerPhone || undefined, saleDate: item.saleDate ? String(item.saleDate).slice(0, 10) : undefined, preTaxAmount: amount, taxRate: Number(item.preTaxAmount) ? Number(item.taxAmount || 0) / Number(item.preTaxAmount) * 100 : 0 }); };
  const editCollection = (item: any) => { const amount = Number(window.prompt("قيمة التحصيل", String(item.amount)) || item.amount); const reference = window.prompt("مرجع الإيصال", item.receiptReference || ""); const normalizedReference = reference === null ? (item.receiptReference || undefined) : (reference || undefined); if (!amount) return; updateCollection.mutate({ id: item.id, projectId: item.projectId, saleId: item.saleId, amount, collectionDestination: item.collectionDestination || "cash", cashAccountId: item.cashAccountId || undefined, escrowReference: item.escrowReference || undefined, receiptReference: normalizedReference, collectionDate: item.collectionDate ? String(item.collectionDate).slice(0, 10) : undefined }); };
  const editCertificate = (item: any) => { const description = window.prompt("وصف المستخلص", item.description || ""); const amount = Number(window.prompt("المبلغ قبل الضريبة", String(item.preTaxAmount)) || item.preTaxAmount); if (!description?.trim() || !amount) return; updateCertificate.mutate({ id: item.id, projectId: item.projectId, certificateNumber: item.certificateNumber, description: description.trim(), technicalSpecifications: item.technicalSpecifications || undefined, preTaxAmount: amount, taxRate: Number(item.preTaxAmount) ? Number(item.taxAmount || 0) / Number(item.preTaxAmount) * 100 : 0, paidAmount: Number(item.paidAmount || 0), certificateDate: item.certificateDate ? String(item.certificateDate).slice(0, 10) : undefined }); };
  const editInvoice = (item: any) => { const partyName = window.prompt("اسم العميل", item.partyName || ""); const amount = Number(window.prompt("المبلغ قبل الضريبة", String(item.amount || item.totalAmount)) || item.amount || item.totalAmount); const revenueLine = item.lines?.find((line: any) => Number(line.credit || 0) > 0) || item.lines?.[0]; if (!partyName?.trim() || !amount || !revenueLine) return; const taxRate = Number(item.amount) ? Number(item.taxAmount || 0) / Number(item.amount) * 100 : 0; const tax = amount * taxRate / 100; updateInvoice.mutate({ id: item.id, projectId: item.projectId || null, partyName: partyName.trim(), partyTaxNumber: item.partyTaxNumber || undefined, documentDate: item.documentDate ? String(item.documentDate).slice(0, 10) : undefined, amount, taxAmount: tax, totalAmount: amount + tax, notes: item.notes || undefined, status: item.status, relatedDocumentType: item.relatedDocumentType || null, relatedDocumentId: item.relatedDocumentId || null, lines: [{ accountId: revenueLine.accountId, projectId: item.projectId || undefined, description: revenueLine.description || "إيراد بيع وحدة", debit: 0, credit: amount + tax }] }); };

  const printCertificate = (item: any) => { const popup = window.open("", "_blank", "width=1000,height=800"); if (!popup) return; popup.document.write(`<html dir="rtl"><head><title>مستخلص ${item.certificateNumber}</title><style>body{font-family:Arial,sans-serif;color:#18324b;padding:40px;direction:rtl}header{border-bottom:4px solid #b28a3b;padding-bottom:20px;margin-bottom:25px}h1{margin:0;font-size:28px}.meta{display:grid;grid-template-columns:1fr 1fr;gap:12px;background:#f5f0e5;padding:18px;border-radius:12px}.box{border:1px solid #d8dee8;padding:16px;border-radius:12px;margin-top:18px}.label{color:#64748b;font-size:12px}.value{font-weight:bold;margin-top:5px}.total{font-size:22px;font-weight:bold;text-align:left;margin-top:24px}@media print{body{padding:20px}}</style></head><body><header><div style="color:#b28a3b;font-weight:bold">مركز المبيعات والتحصيلات العقارية</div><h1>مستخلص بيع على الخارطة</h1><p>${item.certificateNumber || "—"}</p></header><div class="meta"><div><div class="label">المشروع</div><div class="value">${item.projectName || "مشروع بيع على الخارطة"}</div></div><div><div class="label">التاريخ</div><div class="value">${item.certificateDate ? String(item.certificateDate).slice(0,10) : "—"}</div></div><div><div class="label">الجهة</div><div class="value">أمين المشروع / حساب الضمان</div></div><div><div class="label">الحالة</div><div class="value">${item.status || "قيد الاعتماد"}</div></div></div><div class="box"><div class="label">الوصف</div><div class="value">${item.description || "—"}</div></div><div class="box"><div class="label">المواصفات الفنية</div><div class="value">${item.technicalSpecifications || "لا توجد مواصفات فنية مضافة"}</div></div><div class="total">الإجمالي شامل الضريبة: ${money.format(Number(item.totalAmount || 0))} ر.س</div><script>window.onload=()=>window.print()</script></body></html>`); popup.document.close(); };
  const downloadCertificateExcel = (item: any) => { const html = `<table dir="rtl"><tr><th colspan="2">مستخلص بيع على الخارطة</th></tr><tr><td>رقم المستخلص</td><td>${item.certificateNumber || ""}</td></tr><tr><td>المشروع</td><td>${item.projectName || ""}</td></tr><tr><td>الوصف</td><td>${item.description || ""}</td></tr><tr><td>المواصفات الفنية</td><td>${item.technicalSpecifications || ""}</td></tr><tr><td>قبل الضريبة</td><td>${item.preTaxAmount || 0}</td></tr><tr><td>الضريبة</td><td>${item.taxAmount || 0}</td></tr><tr><td>الإجمالي</td><td>${item.totalAmount || 0}</td></tr></table>`; const blob = new Blob([`\ufeff${html}`], { type: "application/vnd.ms-excel;charset=utf-8" }); const url = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = url; link.download = `${item.certificateNumber || "certificate"}.xls`; link.click(); URL.revokeObjectURL(url); };
  const convertCertificateToInvoice = (item: any) => { if (!revenueAccount) { setMessage("لا يوجد حساب إيراد 4101 لتحويل المستخلص إلى فاتورة."); return; } createInvoice.mutate({ documentType: "sales_invoice", projectId: item.projectId, relatedDocumentType: "certificate", relatedDocumentId: item.id, partyName: `مستخلص بيع على الخارطة ${item.certificateNumber || item.id}`, documentDate: item.certificateDate ? String(item.certificateDate).slice(0,10) : today(), amount: Number(item.preTaxAmount || 0), taxAmount: Number(item.taxAmount || 0), totalAmount: Number(item.totalAmount || 0), status: "draft", notes: item.description || "فاتورة محولة من مستخلص بيع على الخارطة", lines: [{ accountId: revenueAccount.id, projectId: item.projectId, description: item.description || `مستخلص ${item.certificateNumber}`, debit: 0, credit: Number(item.totalAmount || 0) }] }, { onSuccess: () => { void utils.erp.accounting.documents.list.invalidate(); setMessage("تم تحويل المستخلص إلى فاتورة مبيعات مسودة مرتبطة به."); }, onError: (error) => setMessage(error.message || "تعذر تحويل المستخلص إلى فاتورة.") }); };

  const requestDelete = (kind: "invoice" | "certificate" | "collection", id: number) => { if (me?.role !== "admin") { setMessage("الحذف متاح للمسؤول فقط."); return; } if (!window.confirm("سيتم حذف السجل نهائيًا بعد التأكيد. هل تريد المتابعة؟")) return; if (kind === "invoice") deleteInvoice.mutate({ id }); else if (kind === "certificate") deleteCertificate.mutate({ id }); else deleteCollection.mutate({ id }); };

  const submitCollection = (event: React.FormEvent) => {
    event.preventDefault();
    const selectedSale = sales.find((item) => item.id === Number(collection.saleId));
    if (!collection.projectId || !collection.saleId || !Number(collection.amount) || !selectedSale) { setMessage("حدد المشروع والبيع وقيمة التحصيل."); return; }
    createCollection.mutate({ projectId: Number(collection.projectId), saleId: Number(collection.saleId), amount: Number(collection.amount), collectionDestination: collection.collectionDestination, cashAccountId: collection.collectionDestination === "escrow" ? undefined : Number(collection.cashAccountId) || undefined, escrowReference: collection.collectionDestination === "escrow" ? collection.escrowReference || undefined : undefined, receiptReference: collection.receiptReference || undefined, collectionDate: collection.collectionDate || undefined });
  };

  return <DashboardLayout><div dir="rtl" className="min-h-screen bg-[#f7f8fa] px-4 py-6 sm:px-8 lg:px-10"><div className="mx-auto max-w-7xl space-y-6">
    <header className="rounded-3xl bg-gradient-to-br from-[#18324b] via-[#214766] to-[#b28a3b] p-6 text-white shadow-xl"><div className="flex flex-col gap-5 lg:flex-row lg:items-end lg:justify-between"><div><Button variant="ghost" className="mb-3 gap-2 px-0 text-white/80 hover:bg-white/10 hover:text-white" onClick={() => setLocation("/")}><ArrowRight className="h-4 w-4" /> العودة للوحة التنفيذ</Button><div className="flex items-center gap-3"><div className="rounded-2xl bg-white/15 p-3"><Building2 className="h-8 w-8" /></div><div><p className="text-sm font-semibold text-[#f5e9c8]">Real Estate Sales Command Center</p><h1 className="text-3xl font-bold">المبيعات والتحصيلات</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-white/75">دورة متكاملة من العميل والوحدة إلى الفاتورة والتحصيل وحساب الضمان، مع إبقاء الترحيل المحاسبي تلقائيًا في الخلفية.</p></div></div></div><div className="grid grid-cols-3 gap-2 text-center"><Metric label="إجمالي المبيعات" value={`${money.format(totalSales)} ر.س`} /><Metric label="المحصل" value={`${money.format(totalCollected)} ر.س`} /><Metric label="المتبقي" value={`${money.format(totalOutstanding)} ر.س`} /></div></div></header>
    <div className="flex flex-wrap gap-2 rounded-2xl border border-slate-200 bg-white p-2 shadow-sm">{([{ key: "overview", label: "نظرة المبيعات", icon: Building2 }, { key: "invoice", label: "إنشاء فاتورة مبيعات", icon: Receipt }, { key: "offPlanCertificate", label: "مستخلص بيع على الخارطة", icon: FileText }, { key: "documents", label: "سجل المستندات", icon: FolderOpen }, { key: "collections", label: "التحصيلات وحساب الضمان", icon: Banknote }, { key: "customers", label: "العملاء والمتابعة", icon: Users }, { key: "units", label: "الوحدات والمخزون البيعي", icon: Landmark }] as const).map(({ key, label, icon: Icon }) => <Button key={key} type="button" variant={activeTab === key ? "default" : "ghost"} className={activeTab === key ? "gap-2 bg-[#18324b]" : "gap-2 text-slate-600"} onClick={() => setActiveTab(key)}><Icon className="h-4 w-4" />{label}</Button>)}</div>
    {message && <div className="rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm font-medium text-emerald-800">{message}</div>}
    {activeTab === "overview" && <><Overview projects={activeProjects} sales={sales} collections={collections} onInvoice={() => setActiveTab("invoice")} onCollection={() => setActiveTab("collections")} /><SalesCenterRegisters sales={sales} invoices={salesInvoices} collections={collections} certificates={offPlanCertificates} onSaleEdit={editSale} onInvoiceEdit={editInvoice} onCollectionEdit={editCollection} onCertificateEdit={editCertificate} /></>}
    {activeTab === "invoice" && <section className="grid gap-6 xl:grid-cols-[1.35fr_0.65fr]"><Card className="border-0 shadow-lg"><CardHeader><CardTitle className="flex items-center gap-2 text-xl text-[#18324b]"><Receipt className="h-5 w-5 text-[#b28a3b]" /> إنشاء فاتورة مبيعات متخصصة</CardTitle><p className="text-sm leading-6 text-slate-500">الفاتورة تحفظ وصف البند، العميل، الوحدة، المشروع، حساب الإيراد، الضريبة، المستند المرتبط، وحالة المسودة أو الإصدار النهائي.</p></CardHeader><CardContent><form className="space-y-5" onSubmit={submitSaleInvoice}><div className="grid gap-4 sm:grid-cols-2"><SelectField label="المشروع *" value={sale.projectId} options={projects.map((p) => ({ value: String(p.id), label: `${p.name} · ${p.projectType === "off_plan_sales" ? "بيع على الخارطة" : "مشروع عقاري"}` }))} onChange={(value) => setSale({ ...sale, projectId: value, unitId: "" })} /><SelectField label="الوحدة المتاحة *" value={sale.unitId} options={availableUnits.map((item) => ({ value: String(item.id), label: `${item.code} — ${item.name} · ${money.format(Number(item.listPrice))} ر.س` }))} onChange={(value) => setSale({ ...sale, unitId: value })} /></div><div className="grid gap-4 sm:grid-cols-[1fr_auto]"><SelectField label="العميل المسجل *" value={sale.customerId} options={customers.map((customer) => ({ value: String(customer.id), label: `${customer.name}${customer.phone ? ` · ${customer.phone}` : ""}` }))} onChange={(value) => { const customer = customers.find((item) => item.id === Number(value)); setSale({ ...sale, customerId: value, customerName: customer?.name || "", customerPhone: customer?.phone || "", customerNationalAddress: customer?.nationalAddress || "", customerTaxNumber: customer?.taxNumber || "" }); }} /><Button type="button" variant="outline" className="mt-6 gap-2" onClick={() => setCustomerOpen(true)}><Plus className="h-4 w-4" /> إنشاء عميل</Button></div><div className="rounded-2xl border border-blue-100 bg-blue-50/60 p-4"><p className="mb-3 text-sm font-bold text-[#18324b]">بيانات العميل في الفاتورة</p><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-5"><Field label="اسم العميل" value={sale.customerName} onChange={(value) => setSale({ ...sale, customerName: value })} /><Field label="الجوال" value={sale.customerPhone} onChange={(value) => setSale({ ...sale, customerPhone: value })} /><Field label="الرقم الضريبي (اختياري)" value={sale.customerTaxNumber} onChange={(value) => setSale({ ...sale, customerTaxNumber: value })} /><Field label="العنوان الوطني (اختياري)" value={sale.customerNationalAddress} onChange={(value) => setSale({ ...sale, customerNationalAddress: value })} /><Field label="تاريخ الفاتورة" type="date" value={sale.saleDate} onChange={(value) => setSale({ ...sale, saleDate: value })} /></div></div><div className="grid gap-4 sm:grid-cols-2"><SelectField label="حالة الفاتورة" value={sale.status} options={[{ value: "draft", label: "حفظ كمسودة" }, { value: "posted", label: "إصدار فاتورة نهائية" }]} onChange={(value) => setSale({ ...sale, status: value as InvoiceStatus })} /></div><Field label="وصف البند المباع *" value={sale.itemDescription} onChange={(value) => setSale({ ...sale, itemDescription: value })} placeholder="مثال: بيع الوحدة A-101 بالدور الأول — دفعة تعاقدية أولى" /><div className="grid gap-4 sm:grid-cols-3"><Field label="المبلغ قبل الضريبة *" type="number" value={sale.preTaxAmount} onChange={(value) => setSale({ ...sale, preTaxAmount: value })} /><SelectField label="نسبة الضريبة" value={sale.taxRate} options={[{ value: "5", label: "5%" }, { value: "15", label: "15%" }]} onChange={(value) => setSale({ ...sale, taxRate: value })} /><div className="rounded-xl bg-[#f5f0e5] p-3"><p className="text-xs text-slate-500">الإجمالي شامل الضريبة</p><p className="mt-2 text-xl font-bold text-[#18324b]">{money.format(totalAmount)} ر.س</p><p className="text-xs text-slate-500">ضريبة: {money.format(taxAmount)} ر.س</p></div></div><div className="rounded-2xl border border-[#b28a3b]/30 bg-[#fffaf0] p-4"><div className="mb-3 flex items-center gap-2"><FilePlus2 className="h-4 w-4 text-[#b28a3b]" /><p className="text-sm font-bold text-[#18324b]">المستند المرتبط</p></div><div className="grid gap-4 sm:grid-cols-2"><SelectField label="النوع" value={sale.relatedDocumentType} options={[{ value: "quotation", label: "عرض سعر" }, { value: "certificate", label: "مستخلص بيع على الخارطة" }]} onChange={(value) => setSale({ ...sale, relatedDocumentType: value as "quotation" | "certificate", relatedDocumentId: "" })} /><SelectField label="المرجع" value={sale.relatedDocumentId} options={relatedOptions} onChange={(value) => setSale({ ...sale, relatedDocumentId: value })} /></div><p className="mt-2 text-xs text-slate-500">لا تظهر مستخلصات المقاولين ضمن مراجع فاتورة المبيعات.</p></div><div className="flex flex-wrap gap-3"><Button type="submit" disabled={!canRecord || createSale.isPending || createInvoice.isPending} className="gap-2 bg-[#18324b] px-6 hover:bg-[#244767]"><Receipt className="h-4 w-4" />{createSale.isPending || createInvoice.isPending ? "جارٍ الحفظ..." : "حفظ البيع والفاتورة"}</Button><Button type="button" variant="outline" onClick={() => setActiveTab("collections")} className="gap-2"><Banknote className="h-4 w-4" />الانتقال للتحصيلات</Button></div></form></CardContent></Card><Card className="border-0 bg-[#18324b] text-white shadow-lg"><CardHeader><CardTitle className="flex items-center gap-2"><ShieldCheck className="h-5 w-5 text-[#f5e9c8]" />ضبط فاتورة البيع</CardTitle></CardHeader><CardContent className="space-y-4 text-sm leading-7 text-white/80"><p>في مشاريع البيع على الخارطة، الفاتورة تسجل الإيراد فقط، بينما التحصيل يسجل كحركة مستقلة ويوجه إلى حساب الضمان أو البنك أو الخزينة.</p><div className="rounded-xl bg-white/10 p-3"><p className="text-xs text-white/60">الحساب الدائن الافتراضي</p><p className="font-bold text-white">{revenueAccount ? `${revenueAccount.code} — ${revenueAccount.name}` : "لم يتم إعداد حساب الإيراد 4101"}</p></div><div className="rounded-xl bg-white/10 p-3"><p className="text-xs text-white/60">حساب ضمان المشروع</p><p className="font-bold text-white">{selectedProject?.projectType === "off_plan_sales" ? (selectedProject.escrowTrusteeName || "محدد في بيانات المشروع") : "اختر مشروع بيع على الخارطة"}</p></div><p className="text-xs text-white/60">الضريبة تحسب تلقائيًا، ووصف البند إلزامي، والمرجع يقتصر على عرض سعر أو مستخلص بيع على الخارطة.</p></CardContent></Card></section>}
    {activeTab === "offPlanCertificate" && <section className="grid gap-6 xl:grid-cols-[1.1fr_0.9fr]"><Card className="border-0 shadow-lg"><CardHeader><CardTitle className="flex items-center gap-2 text-xl text-[#18324b]"><FileText className="h-5 w-5 text-[#b28a3b]" /> إنشاء مستخلص بيع على الخارطة</CardTitle><p className="text-sm leading-6 text-slate-500">مستخلص مخصص للتقديم إلى أمين المشروع، ويمكن اختياره لاحقًا كمستند مرتبط في فاتورة المبيعات.</p></CardHeader><CardContent><form className="space-y-4" onSubmit={submitCertificate}><div className="grid gap-4 sm:grid-cols-2"><SelectField label="مشروع البيع على الخارطة *" value={certificate.projectId} options={projects.filter((project) => project.projectType === "off_plan_sales").map((project) => ({ value: String(project.id), label: project.name }))} onChange={(value) => setCertificate({ ...certificate, projectId: value, unitReferences: "" })} /><Field label="رقم المستخلص *" value={certificate.certificateNumber} onChange={(value) => setCertificate({ ...certificate, certificateNumber: value })} placeholder="مثال: ESC-2026-001" /></div><div className="rounded-2xl border border-blue-100 bg-blue-50/60 p-4"><div className="flex items-center gap-2"><ShieldCheck className="h-4 w-4 text-[#18324b]" /><p className="text-sm font-bold text-[#18324b]">بيانات أمين المشروع وحساب الضمان</p></div><p className="mt-2 text-sm text-slate-600">{projects.find((project) => project.id === Number(certificate.projectId))?.escrowTrusteeName || "سيظهر اسم أمين المشروع من بيانات المشروع بعد اختياره."}</p><p className="mt-1 text-xs text-slate-500">{projects.find((project) => project.id === Number(certificate.projectId))?.escrowStatementReference ? `مرجع الحساب: ${projects.find((project) => project.id === Number(certificate.projectId))?.escrowStatementReference}` : "لم يتم تحديد مرجع حساب الضمان لهذا المشروع."}</p></div><Field label="الوحدات المشمولة" value={certificate.unitReferences} onChange={(value) => setCertificate({ ...certificate, unitReferences: value })} placeholder="مثال: A-101، A-102، B-201" /><Field label="وصف الأعمال أو دفعة البيع *" value={certificate.description} onChange={(value) => setCertificate({ ...certificate, description: value })} placeholder="مثال: مستخلص دفعة تعاقدية مستحقة من مشتري الوحدات" /><Field label="المواصفات الفنية (اختياري)" value={certificate.technicalSpecifications} onChange={(value) => setCertificate({ ...certificate, technicalSpecifications: value })} placeholder="المواصفات أو نطاق الأعمال أو الملاحظات الفنية التي ستظهر في الطباعة" /><div className="grid gap-4 sm:grid-cols-3"><Field label="المبلغ قبل الضريبة *" type="number" value={certificate.preTaxAmount} onChange={(value) => setCertificate({ ...certificate, preTaxAmount: value })} /><SelectField label="نسبة الضريبة" value={certificate.taxRate} options={[{ value: "5", label: "5%" }, { value: "15", label: "15%" }]} onChange={(value) => setCertificate({ ...certificate, taxRate: value })} /><Field label="تاريخ المستخلص" type="date" value={certificate.certificateDate} onChange={(value) => setCertificate({ ...certificate, certificateDate: value })} /></div><div className="rounded-xl bg-[#f5f0e5] p-3 text-sm"><span className="text-slate-500">الإجمالي المتوقع شامل الضريبة: </span><b className="text-[#18324b]">{money.format(Number(certificate.preTaxAmount || 0) * (1 + Number(certificate.taxRate || 0) / 100))} ر.س</b></div><Button type="submit" disabled={!canRecord || createCertificate.isPending} className="w-full gap-2 bg-[#18324b]"><FileText className="h-4 w-4" />{createCertificate.isPending ? "جارٍ إنشاء المستخلص..." : "إنشاء المستخلص وإرساله للاعتماد"}</Button></form></CardContent></Card><Card className="border-0 bg-[#18324b] text-white shadow-lg"><CardHeader><CardTitle className="flex items-center gap-2"><ShieldCheck className="h-5 w-5 text-[#f5e9c8]" /> دورة المستخلص</CardTitle></CardHeader><CardContent className="space-y-4 text-sm leading-7 text-white/80"><p>بعد الحفظ يظهر المستخلص في مراجع فاتورة المبيعات تحت خيار «مستخلص بيع على الخارطة»، ولا تظهر مستخلصات المقاولين ضمن هذا الخيار.</p><div className="rounded-xl bg-white/10 p-3"><p className="text-xs text-white/60">المستخلصات المنشأة</p><p className="mt-1 text-2xl font-bold text-white">{offPlanCertificates.length}</p></div><p className="text-xs text-white/60">يبدأ المستخلص بحالة انتظار اعتماد مدير المشاريع ثم ينتقل لمسار الاعتماد المحدد بالنظام، مع حفظ أمين المشروع والمرجع داخل بيانات المشروع.</p></CardContent></Card></section>}
    {activeTab === "documents" && <DocumentRegister invoices={salesInvoices} certificates={offPlanCertificates} collections={collections} search={documentSearch} filter={documentFilter} onSearch={setDocumentSearch} onFilter={setDocumentFilter} onPreview={setPreviewDocument} onInvoiceEdit={editInvoice} onCertificateEdit={editCertificate} onCollectionEdit={editCollection} onCertificatePdf={printCertificate} onCertificateExcel={downloadCertificateExcel} onCertificateInvoice={convertCertificateToInvoice} onDelete={requestDelete} isAdmin={me?.role === "admin"} />}
    {previewDocument && <Dialog open={Boolean(previewDocument)} onOpenChange={(open) => !open && setPreviewDocument(null)}><DialogContent dir="rtl" className="max-w-2xl"><DialogHeader><DialogTitle>معاينة المستند</DialogTitle></DialogHeader><div className="grid gap-3 sm:grid-cols-2 rounded-2xl bg-slate-50 p-4 text-sm"><div><span className="text-slate-500">النوع</span><p className="font-bold text-[#18324b]">{previewDocument.kindLabel}</p></div><div><span className="text-slate-500">الرقم</span><p className="font-bold text-[#18324b]">{previewDocument.number}</p></div><div><span className="text-slate-500">الطرف / المرجع</span><p className="font-bold text-[#18324b]">{previewDocument.party}</p></div><div><span className="text-slate-500">القيمة</span><p className="font-bold text-[#18324b]">{money.format(Number(previewDocument.amount || 0))} ر.س</p></div><div className="sm:col-span-2"><span className="text-slate-500">الحالة</span><p className="font-bold text-[#18324b]">{previewDocument.status || "—"}</p></div></div></DialogContent></Dialog>}
    {activeTab === "collections" && <section className="grid gap-6 xl:grid-cols-[0.8fr_1.2fr]"><Card className="border-0 shadow-lg"><CardHeader><CardTitle className="flex items-center gap-2 text-xl text-[#18324b]"><Banknote className="h-5 w-5 text-[#b28a3b]" /> تسجيل مقبوضات المبيعات</CardTitle><p className="text-sm text-slate-500">حدد مصدر الإيداع بدقة، مع توجيه تحصيلات البيع على الخارطة إلى حساب الضمان.</p></CardHeader><CardContent><form className="space-y-4" onSubmit={submitCollection}><SelectField label="المشروع *" value={collection.projectId} options={projects.map((p) => ({ value: String(p.id), label: p.name }))} onChange={(value) => setCollection({ ...collection, projectId: value, saleId: "" })} /><SelectField label="فاتورة / بيع العميل *" value={collection.saleId} options={sales.filter((item) => !collection.projectId || item.projectId === Number(collection.projectId)).map((item) => ({ value: String(item.id), label: `بيع #${item.id} — ${item.customerName} · ${money.format(Number(item.totalAmount))} ر.س` }))} onChange={(value) => { const item = sales.find((saleItem) => saleItem.id === Number(value)); setCollection({ ...collection, saleId: value, projectId: item ? String(item.projectId) : collection.projectId }); }} /><div className="grid gap-4 sm:grid-cols-2"><SelectField label="وجهة المبلغ" value={collection.collectionDestination} options={[{ value: "cash", label: "خزينة المكتب" }, { value: "bank", label: "حساب بنكي" }, { value: "escrow", label: "حساب ضمان المشروع" }]} onChange={(value) => setCollection({ ...collection, collectionDestination: value as typeof collection.collectionDestination, cashAccountId: "" })} />{collection.collectionDestination === "escrow" ? <Field label="مرجع إيداع الضمان" value={collection.escrowReference} onChange={(value) => setCollection({ ...collection, escrowReference: value })} placeholder="رقم إشعار الإيداع" /> : <SelectField label="الحساب" value={collection.cashAccountId} options={cashAccounts.filter((account) => account.accountType === collection.collectionDestination).map((account) => ({ value: String(account.id), label: `${account.name} — ${account.code}` }))} onChange={(value) => setCollection({ ...collection, cashAccountId: value })} />}</div><div className="grid gap-4 sm:grid-cols-2"><Field label="المبلغ المقبوض *" type="number" value={collection.amount} onChange={(value) => setCollection({ ...collection, amount: value })} /><Field label="تاريخ التحصيل" type="date" value={collection.collectionDate} onChange={(value) => setCollection({ ...collection, collectionDate: value })} /></div><Field label="مرجع الإيصال" value={collection.receiptReference} onChange={(value) => setCollection({ ...collection, receiptReference: value })} /><Button disabled={!canRecord || createCollection.isPending} className="w-full gap-2 bg-[#18324b]"><Banknote className="h-4 w-4" />{createCollection.isPending ? "جارٍ التسجيل..." : "تسجيل المقبوض"}</Button></form></CardContent></Card><Card className="border-0 shadow-lg"><CardHeader><CardTitle className="text-xl text-[#18324b]">سجل التحصيلات</CardTitle></CardHeader><CardContent className="space-y-3">{collections.length ? collections.map((item) => <div key={item.id} className="rounded-2xl border border-slate-100 bg-slate-50 p-4"><div className="flex items-start justify-between"><div><p className="font-bold text-[#18324b]">تحصيل #{item.id}</p><p className="mt-1 text-xs text-slate-500">{item.collectionDate ? String(item.collectionDate).slice(0, 10) : "بدون تاريخ"} · {item.receiptReference || "بدون مرجع"}</p></div><Badge className={item.status === "received" ? "bg-emerald-100 text-emerald-800" : "bg-amber-100 text-amber-800"}>{item.status === "received" ? "مستلم" : "بانتظار الاعتماد"}</Badge></div><div className="mt-3 grid grid-cols-3 gap-2 text-xs"><div><span className="block text-slate-500">المبلغ</span><b>{money.format(Number(item.amount))} ر.س</b></div><div><span className="block text-slate-500">الوجهة</span><b>{item.collectionDestination === "escrow" ? "حساب ضمان" : item.collectionDestination === "bank" ? "بنك" : "خزينة"}</b></div><div><span className="block text-slate-500">المرجع</span><b>{item.escrowReference || item.receiptReference || "—"}</b></div></div><Button size="sm" variant="outline" className="mt-3" onClick={() => editCollection(item)}>تعديل التحصيل</Button></div>) : <Empty text="لا توجد تحصيلات مسجلة." />}</CardContent></Card></section>}
    {activeTab === "customers" && <section className="space-y-6"><Card className="border-0 shadow-sm"><CardHeader><div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><CardTitle className="flex items-center gap-2 text-xl text-[#18324b]"><Users className="h-5 w-5 text-[#b28a3b]" /> قاعدة العملاء ومتابعة الذمم</CardTitle><p className="mt-1 text-sm text-slate-500">ملف العميل، فواتيره، تحصيلاته، ورصيده المتبقي في مكان واحد.</p></div><div className="flex gap-2"><div className="relative"><Search className="absolute right-3 top-2.5 h-4 w-4 text-slate-400" /><Input value={search} onChange={(event) => setSearch(event.target.value)} className="pr-9" placeholder="بحث بالاسم أو الجوال" /></div><Button type="button" className="gap-2 bg-[#18324b]" onClick={() => setCustomerOpen(true)}><Plus className="h-4 w-4" />عميل جديد</Button></div></div></CardHeader><CardContent><div className="grid gap-3 md:grid-cols-2 lg:grid-cols-3">{filteredCustomers.map((customer) => { const customerSales = sales.filter((item) => item.customerName === customer.name); const customerTotal = customerSales.reduce((sum, item) => sum + Number(item.totalAmount || 0), 0); const customerPaid = collections.filter((item) => customerSales.some((saleItem) => saleItem.id === item.saleId) && item.status === "received").reduce((sum, item) => sum + Number(item.amount || 0), 0); return <div key={customer.id} className="rounded-2xl border border-slate-100 bg-white p-4 shadow-sm"><div className="flex items-start justify-between gap-2"><div><p className="font-bold text-[#18324b]">{customer.name}</p><p className="mt-1 text-xs text-slate-500">{customer.phone || "بدون جوال"} · {customer.taxNumber || "بدون رقم ضريبي"}</p></div><Button size="sm" variant="outline" onClick={() => setEditingCustomer({ id: customer.id, name: customer.name, phone: customer.phone || "" })}><Pencil className="h-3.5 w-3.5" /></Button></div><div className="mt-4 grid grid-cols-3 gap-2 text-xs"><div><span className="block text-slate-500">فواتير</span><b>{customerSales.length}</b></div><div><span className="block text-slate-500">إجمالي</span><b>{money.format(customerTotal)}</b></div><div><span className="block text-slate-500">متبقي</span><b className="text-rose-700">{money.format(Math.max(customerTotal - customerPaid, 0))}</b></div></div></div>; })}</div>{!filteredCustomers.length && <Empty text="لا توجد بيانات عملاء مطابقة." />}</CardContent></Card></section>}
    {activeTab === "units" && <section className="grid gap-6 xl:grid-cols-[0.7fr_1.3fr]"><FormCard title="إضافة وحدة للبيع" icon={Building2}><form className="space-y-3" onSubmit={(event) => { event.preventDefault(); if (!unit.projectId || !unit.code || !unit.name) return; createUnit.mutate({ ...unit, projectId: Number(unit.projectId), listPrice: Number(unit.listPrice || 0) }); }}><SelectField label="المشروع" value={unit.projectId} options={projects.map((p) => ({ value: String(p.id), label: p.name }))} onChange={(value) => setUnit({ ...unit, projectId: value })} /><Field label="كود الوحدة" value={unit.code} onChange={(value) => setUnit({ ...unit, code: value })} /><Field label="اسم الوحدة" value={unit.name} onChange={(value) => setUnit({ ...unit, name: value })} /><Field label="نوع الوحدة" value={unit.type} onChange={(value) => setUnit({ ...unit, type: value })} /><Field label="السعر الإرشادي" type="number" value={unit.listPrice} onChange={(value) => setUnit({ ...unit, listPrice: value })} /><Button className="w-full bg-[#18324b]">حفظ الوحدة</Button></form></FormCard><Card className="border-0 shadow-sm"><CardHeader><CardTitle className="text-xl text-[#18324b]">مخزون الوحدات البيعي</CardTitle></CardHeader><CardContent className="grid gap-3 md:grid-cols-2">{units.map((item) => <div key={item.id} className="rounded-2xl border border-slate-100 p-4"><div className="flex items-center justify-between"><div><p className="font-bold">{item.code} · {item.name}</p><p className="mt-1 text-xs text-slate-500">{projects.find((project) => project.id === item.projectId)?.name || "—"}</p></div><Badge className={item.status === "available" ? "bg-emerald-100 text-emerald-800" : "bg-slate-100 text-slate-700"}>{item.status === "available" ? "متاحة" : "مباعة"}</Badge></div><p className="mt-3 text-lg font-bold text-[#18324b]">{money.format(Number(item.listPrice))} ر.س</p><Button size="sm" variant="outline" className="mt-3" onClick={() => editUnit(item)}>تعديل الوحدة</Button></div>)}</CardContent></Card></section>}
    {invoicePreview && <InvoicePreview invoice={invoicePreview} onClose={() => setInvoicePreview(null)} />}
    {customerOpen && <CustomerModal form={customerForm} setForm={setCustomerForm} pending={createCustomer.isPending} onClose={() => setCustomerOpen(false)} onSave={() => createCustomer.mutate({ name: customerForm.name.trim(), partyType: "customer", entityType: customerForm.entityType, taxNumber: customerForm.taxNumber || undefined, commercialRegistration: customerForm.commercialRegistration || undefined, nationalAddress: customerForm.nationalAddress || undefined, address: customerForm.address || undefined, phone: customerForm.phone || undefined, email: customerForm.email || undefined })} />}
    {editingCustomer && <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/40 p-4"><div className="w-full max-w-md rounded-2xl bg-white p-5 shadow-2xl"><h2 className="text-lg font-bold text-[#18324b]">تعديل بيانات العميل</h2><div className="mt-4 space-y-3"><Field label="اسم العميل" value={editingCustomer.name} onChange={(value) => setEditingCustomer({ ...editingCustomer, name: value })} /><Field label="الجوال" value={editingCustomer.phone} onChange={(value) => setEditingCustomer({ ...editingCustomer, phone: value })} /><div className="flex gap-2"><Button type="button" className="bg-[#18324b]" onClick={() => updateCustomer.mutate({ id: editingCustomer.id, customerName: editingCustomer.name, customerPhone: editingCustomer.phone || undefined })}>حفظ</Button><Button type="button" variant="outline" onClick={() => setEditingCustomer(null)}>إلغاء</Button></div></div></div></div>}
  </div></div></DashboardLayout>;
}

const emptyUnit = { projectId: "", code: "", name: "", type: "", listPrice: "" };
const emptyCollection = { projectId: "", saleId: "", amount: "", collectionDestination: "cash" as "cash" | "bank" | "escrow", cashAccountId: "", escrowReference: "", receiptReference: "", collectionDate: today() };
const emptyCertificate = { projectId: "", certificateNumber: "", unitReferences: "", description: "", technicalSpecifications: "", preTaxAmount: "", taxRate: "15", certificateDate: today() };
const emptyCustomer = { name: "", entityType: "company" as "company" | "individual", taxNumber: "", commercialRegistration: "", nationalAddress: "", address: "", phone: "", email: "" };

function Metric({ label, value }: { label: string; value: string }) { return <div className="rounded-2xl bg-white/15 px-4 py-3"><p className="text-[11px] text-white/65">{label}</p><p className="mt-1 text-lg font-bold text-white">{value}</p></div>; }
function FormCard({ title, icon: Icon, children }: { title: string; icon: typeof Building2; children: React.ReactNode }) { return <Card className="border-0 shadow-sm"><CardHeader><CardTitle className="flex items-center gap-2 text-lg text-[#18324b]"><Icon className="h-5 w-5 text-[#b28a3b]" />{title}</CardTitle></CardHeader><CardContent>{children}</CardContent></Card>; }
function Field({ label, value, onChange, type = "text", placeholder }: { label: string; value: string; onChange: (value: string) => void; type?: string; placeholder?: string }) { return <div className="space-y-1.5"><Label className="text-xs text-slate-600">{label}</Label><Input dir="rtl" type={type} value={value} placeholder={placeholder} onChange={(event) => onChange(event.target.value)} className="h-10 border-slate-200" /></div>; }
function SelectField({ label, value, options, onChange }: { label: string; value: string; options: { value: string; label: string }[]; onChange: (value: string) => void }) { return <div className="space-y-1.5"><Label className="text-xs text-slate-600">{label}</Label><select value={value} onChange={(event) => onChange(event.target.value)} className="h-10 w-full rounded-md border border-slate-200 bg-white px-2 text-sm" required><option value="">اختر...</option>{options.map((option) => <option key={option.value} value={option.value}>{option.label}</option>)}</select></div>; }
function Empty({ text }: { text: string }) { return <div className="rounded-2xl border border-dashed border-slate-200 py-12 text-center text-sm text-slate-400">{text}</div>; }
function Overview({ projects, sales, collections, onInvoice, onCollection }: { projects: any[]; sales: any[]; collections: any[]; onInvoice: () => void; onCollection: () => void }) { return <section className="grid gap-6 lg:grid-cols-2"><Card className="border-0 shadow-sm"><CardHeader><CardTitle className="text-xl text-[#18324b]">مسار العمل العقاري</CardTitle></CardHeader><CardContent className="space-y-3"><Step icon={Users} title="العميل" text="بيانات العميل الشاملة والسجل التجاري والعنوان الوطني." /><Step icon={Building2} title="الوحدة" text="الوحدة المتاحة وسعرها ومشروعها ومرحلتها." /><Step icon={Receipt} title="الفاتورة" text="فاتورة ضريبية بوصف بند واضح وربط بإيراد المشروع." /><Step icon={ShieldCheck} title="حساب الضمان" text="توجيه تحصيلات مشاريع البيع على الخارطة إلى الحساب المحدد." /><div className="flex flex-wrap gap-2 pt-2"><Button className="gap-2 bg-[#18324b]" onClick={onInvoice}><Receipt className="h-4 w-4" />إنشاء فاتورة مبيعات</Button><Button variant="outline" className="gap-2" onClick={onCollection}><Banknote className="h-4 w-4" />تسجيل تحصيل</Button></div></CardContent></Card><Card className="border-0 shadow-sm"><CardHeader><CardTitle className="text-xl text-[#18324b]">ملخص المحفظة</CardTitle></CardHeader><CardContent className="grid gap-3 sm:grid-cols-3"><Summary label="المشاريع النشطة" value={String(projects.length)} /><Summary label="حركات البيع" value={String(sales.length)} /><Summary label="حركات التحصيل" value={String(collections.length)} /></CardContent></Card></section>; }
function Step({ icon: Icon, title, text }: { icon: typeof Users; title: string; text: string }) { return <div className="flex gap-3 rounded-xl bg-slate-50 p-3"><div className="rounded-lg bg-[#f5f0e5] p-2"><Icon className="h-4 w-4 text-[#b28a3b]" /></div><div><p className="font-bold text-[#18324b]">{title}</p><p className="text-xs leading-6 text-slate-500">{text}</p></div></div>; }
function SalesCenterRegisters({ sales, invoices, collections, certificates, onSaleEdit, onInvoiceEdit, onCollectionEdit, onCertificateEdit }: { sales: any[]; invoices: any[]; collections: any[]; certificates: any[]; onSaleEdit: (item: any) => void; onInvoiceEdit: (item: any) => void; onCollectionEdit: (item: any) => void; onCertificateEdit: (item: any) => void }) { return <section className="grid gap-6 lg:grid-cols-2"><Card className="border-0 shadow-sm"><CardHeader><CardTitle className="text-lg text-[#18324b]">حركة الفواتير والمبيعات</CardTitle></CardHeader><CardContent className="space-y-2">{invoices.slice(-5).reverse().map((item) => <div key={`invoice-${item.id}`} className="flex items-center justify-between rounded-xl border border-slate-100 p-3 text-sm"><div><b>{item.documentNumber || `فاتورة #${item.id}`}</b><p className="text-xs text-slate-500">{item.partyName || "بدون عميل"} · {money.format(Number(item.totalAmount || 0))} ر.س</p></div><Button size="sm" variant="outline" onClick={() => onInvoiceEdit(item)}>تعديل الفاتورة</Button></div>)}{sales.slice(-5).reverse().map((item) => <div key={`sale-${item.id}`} className="flex items-center justify-between rounded-xl border border-slate-100 p-3 text-sm"><div><b>بيع #{item.id}</b><p className="text-xs text-slate-500">{item.customerName} · {money.format(Number(item.totalAmount || 0))} ر.س</p></div><Button size="sm" variant="outline" onClick={() => onSaleEdit(item)}>تعديل البيع</Button></div>)}{!invoices.length && !sales.length && <Empty text="لا توجد فواتير أو مبيعات بعد." />}</CardContent></Card><Card className="border-0 shadow-sm"><CardHeader><CardTitle className="text-lg text-[#18324b]">المستخلصات والتحصيلات</CardTitle></CardHeader><CardContent className="space-y-2">{certificates.slice(-4).reverse().map((item) => <div key={`certificate-${item.id}`} className="flex items-center justify-between rounded-xl border border-slate-100 p-3 text-sm"><div><b>{item.certificateNumber}</b><p className="text-xs text-slate-500">مستخلص بيع على الخارطة · {money.format(Number(item.totalAmount || 0))} ر.س</p></div><Button size="sm" variant="outline" onClick={() => onCertificateEdit(item)}>تعديل المستخلص</Button></div>)}{collections.slice(-4).reverse().map((item) => <div key={`collection-${item.id}`} className="flex items-center justify-between rounded-xl border border-slate-100 p-3 text-sm"><div><b>تحصيل #{item.id}</b><p className="text-xs text-slate-500">{money.format(Number(item.amount || 0))} ر.س · {item.status}</p></div><Button size="sm" variant="outline" onClick={() => onCollectionEdit(item)}>تعديل التحصيل</Button></div>)}{!certificates.length && !collections.length && <Empty text="لا توجد مستخلصات أو تحصيلات بعد." />}</CardContent></Card></section>; }
function DocumentRegister({ invoices, certificates, collections, search, filter, onSearch, onFilter, onPreview, onInvoiceEdit, onCertificateEdit, onCollectionEdit, onCertificatePdf, onCertificateExcel, onCertificateInvoice, onDelete, isAdmin }: { invoices: any[]; certificates: any[]; collections: any[]; search: string; filter: "all" | "invoice" | "certificate" | "collection"; onSearch: (value: string) => void; onFilter: (value: "all" | "invoice" | "certificate" | "collection") => void; onPreview: (item: any) => void; onInvoiceEdit: (item: any) => void; onCertificateEdit: (item: any) => void; onCollectionEdit: (item: any) => void; onCertificatePdf: (item: any) => void; onCertificateExcel: (item: any) => void; onCertificateInvoice: (item: any) => void; onDelete: (kind: "invoice" | "certificate" | "collection", id: number) => void; isAdmin: boolean }) { const rows = [...(filter === "all" || filter === "invoice" ? invoices.map((item) => ({ ...item, kind: "invoice" as const, kindLabel: "فاتورة مبيعات", number: item.documentNumber || `فاتورة #${item.id}`, party: item.partyName || "بدون عميل", amount: item.totalAmount })) : []), ...(filter === "all" || filter === "certificate" ? certificates.map((item) => ({ ...item, kind: "certificate" as const, kindLabel: "مستخلص بيع على الخارطة", number: item.certificateNumber || `مستخلص #${item.id}`, party: "أمين المشروع", amount: item.totalAmount })) : []), ...(filter === "all" || filter === "collection" ? collections.map((item) => ({ ...item, kind: "collection" as const, kindLabel: "تحصيل مبيعات", number: `تحصيل #${item.id}`, party: item.receiptReference || "بدون مرجع", amount: item.amount })) : [])].filter((item) => `${item.number} ${item.party} ${item.kindLabel}`.toLowerCase().includes(search.toLowerCase())).sort((a, b) => Number(b.id) - Number(a.id)); const total = rows.reduce((sum, item) => sum + Number(item.amount || 0), 0); const preview = (item: any) => onPreview({ ...item, kindLabel: item.kindLabel, number: item.number, party: item.party, amount: item.amount }); return <section className="space-y-5"><Card className="border-0 shadow-lg"><CardHeader><div className="flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between"><div><CardTitle className="flex items-center gap-2 text-xl text-[#18324b]"><FolderOpen className="h-5 w-5 text-[#b28a3b]" /> سجل مستندات المبيعات والتحصيلات</CardTitle><p className="mt-1 text-sm text-slate-500">أرشيف موحد قابل للبحث، يعرض علاقة الفاتورة بالمستخلص والتحصيل وحالة كل مستند.</p></div><div className="grid grid-cols-3 gap-2 text-center"><Summary label="السجلات" value={String(rows.length)} /><Summary label="إجمالي القيم" value={`${money.format(total)} ر.س`} /><Summary label="الحذف" value={isAdmin ? "متاح للمسؤول" : "مقيّد"} /></div></div></CardHeader><CardContent><div className="flex flex-col gap-3 md:flex-row"><Field label="بحث" value={search} onChange={onSearch} placeholder="رقم المستند، العميل، المرجع..." /><div className="flex flex-wrap items-end gap-2">{([{ value: "all", label: "الكل" }, { value: "invoice", label: "فواتير" }, { value: "certificate", label: "مستخلصات" }, { value: "collection", label: "تحصيلات" }] as const).map((option) => <Button key={option.value} type="button" size="sm" variant={filter === option.value ? "default" : "outline"} className={filter === option.value ? "bg-[#18324b]" : ""} onClick={() => onFilter(option.value)}>{option.label}</Button>)}</div></div></CardContent></Card><Card className="border-0 shadow-sm"><CardContent className="space-y-3 pt-6">{rows.map((item) => <div key={`${item.kind}-${item.id}`} className="flex flex-col gap-3 rounded-2xl border border-slate-100 bg-white p-4 lg:flex-row lg:items-center lg:justify-between"><div className="flex items-start gap-3"><div className="rounded-xl bg-[#f5f0e5] p-3 text-[#18324b]"><FileText className="h-5 w-5" /></div><div><div className="flex flex-wrap items-center gap-2"><b className="text-[#18324b]">{item.number}</b><Badge variant="outline">{item.kindLabel}</Badge><Badge className={item.status === "approved" || item.status === "received" || item.status === "posted" ? "bg-emerald-100 text-emerald-800" : "bg-amber-100 text-amber-800"}>{item.status || "مسودة"}</Badge></div><p className="mt-1 text-sm text-slate-500">{item.party} · {money.format(Number(item.amount || 0))} ر.س</p></div></div><div className="flex flex-wrap gap-2"><Button size="sm" variant="outline" onClick={() => preview(item)}>معاينة</Button><Button size="sm" variant="outline" onClick={() => item.kind === "invoice" ? onInvoiceEdit(item) : item.kind === "certificate" ? onCertificateEdit(item) : onCollectionEdit(item)}>تعديل</Button>{item.kind === "certificate" && <><Button size="sm" variant="outline" onClick={() => onCertificatePdf(item)}>PDF</Button><Button size="sm" variant="outline" onClick={() => onCertificateExcel(item)}>Excel</Button><Button size="sm" variant="outline" onClick={() => onCertificateInvoice(item)}>تحويل لفاتورة</Button></>}<Button size="sm" variant="ghost" className={isAdmin ? "text-rose-700 hover:bg-rose-50" : "text-slate-400"} disabled={!isAdmin} onClick={() => onDelete(item.kind, item.id)}>حذف</Button></div></div>)}{!rows.length && <Empty text="لا توجد مستندات مطابقة للفلاتر الحالية." />}</CardContent></Card></section>; }
function Summary({ label, value }: { label: string; value: string }) { return <div className="rounded-xl bg-[#f5f0e5] p-4 text-center"><p className="text-xs text-slate-500">{label}</p><p className="mt-2 text-2xl font-bold text-[#18324b]">{value}</p></div>; }
function CustomerModal({ form, setForm, pending, onClose, onSave }: { form: typeof emptyCustomer; setForm: (form: typeof emptyCustomer) => void; pending: boolean; onClose: () => void; onSave: () => void }) { return <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/40 p-4"><div className="w-full max-w-2xl rounded-2xl bg-white p-5 shadow-2xl" dir="rtl"><div className="flex items-center justify-between"><h2 className="text-xl font-bold text-[#18324b]">إضافة عميل شامل</h2><Button type="button" variant="outline" onClick={onClose}>إغلاق</Button></div><div className="mt-4 grid gap-3 sm:grid-cols-2"><Field label="اسم العميل *" value={form.name} onChange={(value) => setForm({ ...form, name: value })} /><SelectField label="نوع الكيان" value={form.entityType} options={[{ value: "company", label: "شركة" }, { value: "individual", label: "فرد" }]} onChange={(value) => setForm({ ...form, entityType: value as typeof form.entityType })} /><Field label="الرقم الضريبي اختياري" value={form.taxNumber} onChange={(value) => setForm({ ...form, taxNumber: value })} /><Field label="السجل التجاري" value={form.commercialRegistration} onChange={(value) => setForm({ ...form, commercialRegistration: value })} /><Field label="العنوان الوطني" value={form.nationalAddress} onChange={(value) => setForm({ ...form, nationalAddress: value })} /><Field label="العنوان التفصيلي" value={form.address} onChange={(value) => setForm({ ...form, address: value })} /><Field label="الجوال" value={form.phone} onChange={(value) => setForm({ ...form, phone: value })} /><Field label="البريد الإلكتروني" value={form.email} onChange={(value) => setForm({ ...form, email: value })} /></div><Button type="button" disabled={!form.name.trim() || pending} className="mt-5 w-full bg-[#18324b]" onClick={onSave}>{pending ? "جارٍ الحفظ..." : "حفظ العميل"}</Button></div></div>; }
function InvoicePreview({ invoice, onClose }: { invoice: any; onClose: () => void }) { return <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/50 p-4"><div className="w-full max-w-3xl rounded-2xl bg-white p-6 shadow-2xl" dir="rtl"><div className="flex items-start justify-between border-b border-slate-200 pb-4"><div><p className="text-xs text-slate-500">معاينة فاتورة المبيعات</p><h2 className="text-2xl font-bold text-[#18324b]">{invoice.documentNumber}</h2></div><Button variant="outline" onClick={onClose}>إغلاق</Button></div><div className="mt-5 grid gap-4 sm:grid-cols-2"><div className="rounded-xl bg-slate-50 p-4"><p className="text-xs text-slate-500">العميل</p><p className="mt-1 font-bold">{invoice.partyName}</p><p className="mt-3 text-xs text-slate-500">المشروع</p><p className="mt-1 font-bold">{invoice.projectName || "—"}</p><p className="mt-3 text-xs text-slate-500">الرقم الضريبي</p><p className="mt-1 font-bold">{invoice.customerTaxNumber || "غير مضاف"}</p><p className="mt-3 text-xs text-slate-500">العنوان الوطني</p><p className="mt-1 font-bold">{invoice.customerNationalAddress || "غير مضاف"}</p></div><div className="rounded-xl bg-[#f5f0e5] p-4"><p className="text-xs text-slate-500">التاريخ</p><p className="mt-1 font-bold">{invoice.documentDate}</p><p className="mt-3 text-xs text-slate-500">الحالة</p><p className="mt-1 font-bold">فاتورة محفوظة</p></div></div><div className="mt-5 overflow-hidden rounded-xl border border-slate-300"><div className="grid grid-cols-4 bg-[#18324b] p-3 text-sm font-bold text-white"><span>البند</span><span>قبل الضريبة</span><span>الضريبة</span><span>الإجمالي</span></div><div className="grid grid-cols-4 p-4 text-sm"><span>{invoice.description}</span><span>{money.format(invoice.amount)}</span><span>{money.format(invoice.taxAmount)}</span><span className="font-bold">{money.format(invoice.totalAmount)}</span></div></div><div className="mt-5 flex justify-end gap-2"><Button variant="outline" onClick={() => window.print()}><FileText className="ml-2 h-4 w-4" />طباعة / PDF</Button><Button className="bg-[#18324b]" onClick={onClose}>تم</Button></div></div></div>; }
